<header><h1>My Bookmarks</h1></header>
<main>
  <section class="capture">
    <label for="url">Paste a link to save</label>
    <input id="url" type="text" placeholder="https://…" autocomplete="off" />
    <div class="row">
      <button id="save" class="primary" disabled>Save link</button>
      <span class="hint" id="cap-hint">Enter a link to enable saving.</span>
    </div>
    <p class="examples">No link handy? Try one of these examples:
