<script>
  // --- Simulated page-metadata lookup ---------------------------------------
  // In the real app this is read from the actual page. Here a few example links
  // carry realistic details; anything else gets a reasonable fallback.
  var CANNED = {
    'https://www.nasa.gov/mars-exploration': {
      title:'Mars Exploration Program — NASA',
      desc:'NASA’s ongoing robotic exploration of Mars, including rovers, orbiters and future crewed mission planning.',
      icon:'https://www.google.com/s2/favicons?domain=nasa.gov&sz=64',
      image:'https://images.unsplash.com/photo-1614728263952-84ea256f9679?w=800&q=60'
    },
    'https://realpython.com/python-decorators': {
      title:'Primer on Python Decorators – Real Python',
      desc:'Learn how decorators work and how to use them to wrap and extend the behaviour of your functions and classes.',
      icon:'https://www.google.com/s2/favicons?domain=realpython.com&sz=64',
      image:'https://images.unsplash.com/photo-1526379095098-d400fd0bf935?w=800&q=60'
