    'https://www.seriouseats.com/perfect-pasta': {
      title:'The Food Lab: How to Cook Perfect Pasta',
      desc:'A step-by-step guide to cooking pasta properly, from salting the water to timing the sauce.',
      icon:'https://www.google.com/s2/favicons?domain=seriouseats.com&sz=64',
      image:'https://images.unsplash.com/photo-1551183053-bf91a1d81141?w=800&q=60'
    }
  };

  var items = [];
  var seq = 0;
  var urlEl = document.getElementById('url');
  var saveEl = document.getElementById('save');
  var listEl = document.getElementById('list');
  var hintEl = document.getElementById('cap-hint');
  var toastEl = document.getElementById('toast');

  function normalize(u){
    u = (u||'').trim();
    if(!u) return '';
    if(!/^https?:\/\//i.test(u)) u = 'https://' + u;
    return u.replace(/\/+$/,''); // trailing slash ignored for duplicate matching
  }
  function hostOf(u){ try { return new URL(u).hostname.replace(/^www\./,''); } catch(e){ return u; } }
  function fmtDate(d){
    return d.toLocaleDateString(undefined,{month:'short',day:'numeric'}) + ' · ' +
           d.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'});
  }
  function toast(msg){
    toastEl.textContent = msg; toastEl.classList.add('show');
    clearTimeout(toast._t); toast._t = setTimeout(function(){ toastEl.classList.remove('show'); },2400);
  }
  function escapeHtml(s){ return (s||'').replace(/[&<>"]/g,function(c){
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }

  function fetchMeta(url){
    if(CANNED[url]) return CANNED[url];
    var h = hostOf(url);
    return { title: h.charAt(0).toUpperCase()+h.slice(1), desc:'',
             icon:'https://www.google.com/s2/favicons?domain='+h+'&sz=64', image:'' };
  }

  function render(){
    if(items.length === 0){
      listEl.innerHTML = '<div class="empty">No links saved yet. Paste one above to get started.</div>';
      return;
    }
    listEl.innerHTML = '';
    items.forEach(function(it){
      var el = document.createElement('div');
      el.className = 'item'; el.id = 'item-'+it.id;
      var preview = it.image ? '<img class="preview" src="'+it.image+'" alt="" onerror="this.style.display=\'none\'">' : '';
      var favInner = it.icon ? '<img src="'+it.icon+'" alt="" onerror="this.parentNode.textContent=\'🔖\'">' : '🔖';
      var descHtml = it.desc ? '<p class="desc">'+escapeHtml(it.desc)+'</p>' : '';
      el.innerHTML =
        preview +
        '<div class="content">' +
          '<div class="fav">'+favInner+'</div>' +
          '<div class="body">' +
            '<p class="title"><a href="'+it.url+'" target="_blank" rel="noopener">'+escapeHtml(it.title)+'</a></p>' +
            descHtml +
            '<p class="url">'+escapeHtml(it.url)+'</p>' +
            '<p class="meta">Saved '+fmtDate(it.saved)+'</p>' +
            '<div class="actions"><button class="ghost" data-edit="'+it.id+'">Edit</button></div>' +
          '</div>' +
        '</div>';
      if(it.editing) el.appendChild(buildEditor(it));
      listEl.appendChild(el);
    });
  }

  function buildEditor(it){
    var box = document.createElement('div');
    box.className = 'edit';
    box.innerHTML =
      '<label>Title</label><input data-f="title" value="'+escapeHtml(it.title)+'">' +
      '<label>Description</label><textarea data-f="desc">'+escapeHtml(it.desc||'')+'</textarea>' +
      '<div class="row" style="margin-top:0"><button class="primary" data-save-edit="'+it.id+'">Save changes</button>' +
      '<button class="ghost" data-cancel-edit="'+it.id+'">Cancel</button></div>';
    return box;
  }

  function findByUrl(url){ for(var i=0;i<items.length;i++){ if(items[i].url===url) return items[i]; } return null; }
  function flash(id){
    var el=document.getElementById('item-'+id); if(!el) return;
    el.scrollIntoView({behavior:'smooth',block:'center'});
    el.classList.add('flash'); setTimeout(function(){ el.classList.remove('flash'); },1400);
  }

  function refreshButton(){
    var has = urlEl.value.trim().length > 0;
    saveEl.disabled = !has;
    hintEl.textContent = has ? 'Ready to save.' : 'Enter a link to enable saving.';
  }

  function save(){
    var raw = urlEl.value.trim(); if(!raw) return;
    var url = normalize(raw);
    var existing = findByUrl(url);
    if(existing){
      items.forEach(function(x){ x.editing=false; });
      existing.editing = true;
      urlEl.value=''; refreshButton(); render();
      flash(existing.id);
      toast('You already saved this link — opened it for editing.');
      return;
    }
    var m = fetchMeta(url);
    var it = { id:++seq, url:url, title:m.title, desc:m.desc, icon:m.icon, image:m.image,
               saved:new Date(), editing:false };
    items.unshift(it);
    urlEl.value=''; refreshButton(); render(); urlEl.focus();
    toast('Saved “'+it.title+'”');
  }

  listEl.addEventListener('click', function(e){
    var t = e.target;
    if(t.dataset.edit){ var it=byId(+t.dataset.edit); items.forEach(function(x){x.editing=false;}); it.editing=true; render(); }
    else if(t.dataset.cancelEdit){ var c=byId(+t.dataset.cancelEdit); c.editing=false; render(); }
    else if(t.dataset.saveEdit){
      var s=byId(+t.dataset.saveEdit);
      var box=t.closest('.edit');
      s.title=(box.querySelector('[data-f=title]').value.trim())||s.title;
      s.desc=box.querySelector('[data-f=desc]').value.trim();
      s.editing=false; render(); flash(s.id); toast('Changes saved.');
    }
  });
  function byId(id){ for(var i=0;i<items.length;i++) if(items[i].id===id) return items[i]; return null; }

  document.querySelectorAll('.chip').forEach(function(c){
    c.addEventListener('click', function(){ urlEl.value=c.dataset.ex; refreshButton(); urlEl.focus(); });
  });
  urlEl.addEventListener('input', refreshButton);
  urlEl.addEventListener('keydown', function(e){ if(e.key==='Enter'){ e.preventDefault(); save(); }});
  saveEl.addEventListener('click', save);

  render(); refreshButton();
  document.body.setAttribute('data-harness-ready','true');
</script>
</body>
